map-capitol-reef.html:
:root{--nav-h:44px}
.pwa-nav{height:calc(var(--nav-h) + env(safe-area-inset-top,0px));padding:env(safe-area-inset-top,0px) 0 0;border-top:0;border-bottom:1px solid rgba(203,168,90,.32);background:rgba(13,10,24,.96)}
.pwa-navitem{color:#7A6E55;transition:color .15s}.pwa-navitem.active{color:#CBA85A}.pwa-navitem:active{color:#E6CC85}
#es-top{padding-bottom:26px;background:linear-gradient(to bottom,rgba(8,6,16,.95) 0%,rgba(8,6,16,.92) 68%,rgba(8,6,16,.55) 86%,transparent 100%)}
#es-zoom{bottom:calc(env(safe-area-inset-bottom,0px) + 58px);transition:transform .28s cubic-bezier(.22,.61,.36,1),opacity .2s}
#es-loc{bottom:calc(env(safe-area-inset-bottom,0px) + 144px);transition:transform .28s cubic-bezier(.22,.61,.36,1),opacity .2s}
body.card-open #es-zoom,body.card-open #es-loc{transform:translateY(calc(46px - var(--card-h,230px)))}
body.drawer-open #es-zoom,body.drawer-open #es-loc{opacity:0;pointer-events:none}
#es-card{max-height:min(64vh,420px);overflow-y:auto}
#es-drawer{transform:translateY(calc(100% - 46px - env(safe-area-inset-bottom,0px)))}
#es-drawer.open{transform:translateY(0)}

